const require_browser = require("../utils/browser.js");
const require_index = require("../useEventListener/index.js");
let react = require("react");
//#region src/usePageLeave/index.ts
function usePageLeave() {
	const [isLeft, setIsLeft] = (0, react.useState)(false);
	const handler = (event) => {
		if (!window) return;
		event = event || window.event;
		const from = event.relatedTarget || event.toElement;
		setIsLeft(!from);
	};
	require_index.useEventListener("mouseout", handler, require_browser.defaultWindow, { passive: true });
	require_index.useEventListener("mouseleave", handler, require_browser.defaultDocument, { passive: true });
	require_index.useEventListener("mouseenter", handler, require_browser.defaultDocument, { passive: true });
	return isLeft;
}
//#endregion
exports.usePageLeave = usePageLeave;
